import {readSections} from './explorer-model.js';
export function buildSlides(project,ids){const nodes=new Map(project.nodes.map(n=>[n.id,n]));ids=[...new Set(ids)].filter(id=>nodes.has(id));const slides=[{type:'overview',ids:project.nodes.map(n=>n.id)}];for(const id of [...new Set(ids)]){if(!nodes.has(id))continue;slides.push({type:'idea',id,ids:[id]});const children=[...new Set(project.edges.filter(e=>e.source===id&&nodes.has(e.target)&&e.target!==id).map(e=>e.target))];for(let i=0;i<children.length;i++)slides.push({type:'feature',id,feature:children[i],ids:[id,...children.slice(0,i+1)]});}const favorites=ids.filter(id=>nodes.get(id)?.favorite).slice(0,3);if(favorites.length>1)slides.push({type:'compare',ids:favorites});return slides;}
export function configurePresentation(api){
 const p=api.project(),esc=api.esc;let order=(p.presentationIds||[]).filter(id=>p.nodes.some(n=>n.id===id));if(!order.length){const root=p.nodes.find(n=>n.text==='IDEIAS DE PROJETOS');order=root?p.edges.filter(e=>e.source===root.id).map(e=>e.target):p.nodes.filter(n=>n.favorite).map(n=>n.id);if(!order.length)order=p.nodes.slice(0,5).map(n=>n.id);}order=[...new Set(order)];
 const d=document.createElement('dialog');d.className='presentation-config';d.innerHTML='<button class="dialog-close" aria-label="Fechar configuração">×</button><h2>Montar apresentação</h2><p>Escolha as ideias e organize a sequência. As funcionalidades aparecem uma a uma. Arraste para ordenar ou use as setas.</p><input aria-label="Buscar ideias para apresentar" placeholder="Buscar ideias…"><div class="presentation-order"></div><div class="presentation-choices"></div><button class="primary start-show">Iniciar apresentação</button>';document.body.append(d);d.showModal();let dragged=null;
 const render=()=>{d.querySelector('.presentation-order').innerHTML=order.map((id,i)=>{const n=p.nodes.find(n=>n.id===id);return `<div draggable="true" data-slide-id="${esc(id)}"><span>${i+1}. ${esc(n.text)}</span><button data-up="${i}" aria-label="Subir ${esc(n.text)}" ${i===0?'disabled':''}>↑</button><button data-down="${i}" aria-label="Descer ${esc(n.text)}" ${i===order.length-1?'disabled':''}>↓</button><button data-remove="${i}" aria-label="Remover ${esc(n.text)}">×</button></div>`;}).join('');const q=d.querySelector('input').value.toLocaleLowerCase();d.querySelector('.presentation-choices').innerHTML=p.nodes.filter(n=>!order.includes(n.id)&&n.text.toLocaleLowerCase().includes(q)).map(n=>`<button data-pick="${esc(n.id)}">+ ${esc(n.text)}</button>`).join('');d.querySelector('.start-show').disabled=!order.length;
 d.querySelectorAll('[data-slide-id]').forEach(el=>{el.ondragstart=()=>dragged=el.dataset.slideId;el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();if(!dragged||dragged===el.dataset.slideId)return;order=order.filter(id=>id!==dragged);order.splice(order.indexOf(el.dataset.slideId),0,dragged);render();};});};
 d.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.classList.contains('dialog-close'))d.close();if(b.dataset.pick){order.push(b.dataset.pick);render();}for(const [key,delta]of [['up',-1],['down',1]])if(b.dataset[key]!==undefined){const i=Number(b.dataset[key]);[order[i],order[i+delta]]=[order[i+delta],order[i]];render();}if(b.dataset.remove!==undefined){order.splice(Number(b.dataset.remove),1);render();}if(b.classList.contains('start-show')){if(!api.readonly()){p.presentationIds=[...order];api.changed();}d.close();startPresentation(p,order,esc);}};d.onclose=()=>d.remove();d.querySelector('input').oninput=render;render();
}
function startPresentation(p,order,esc){const slides=buildSlides(p,order),nodes=new Map(p.nodes.map(n=>[n.id,n]));let index=0;const stage=document.createElement('dialog');stage.className='presentation-stage';stage.innerHTML='<div class="slide-body"></div><nav class="slide-controls"><button data-action="prev" aria-label="Slide anterior">←</button><span class="slide-count" aria-live="polite"></span><button data-action="next" aria-label="Próximo slide">→</button><button data-action="full">Tela cheia</button><button data-action="exit">Sair · Esc</button></nav>';document.body.append(stage);stage.showModal();
 const graph=(ids,highlight)=>{const shown=ids.map(id=>nodes.get(id)).filter(Boolean);if(!shown.length)return '';const x=Math.min(...shown.map(n=>n.x))-50,y=Math.min(...shown.map(n=>n.y))-50,w=Math.max(...shown.map(n=>n.x+210))-x+50,h=Math.max(...shown.map(n=>n.y+84))-y+50;return `<svg class="slide-map" viewBox="${x} ${y} ${w} ${h}" role="img" aria-label="Mapa das ideias deste slide">${p.edges.filter(e=>ids.includes(e.source)&&ids.includes(e.target)).map(e=>{const a=nodes.get(e.source),b=nodes.get(e.target);return `<path d="M${a.x+105},${a.y+42} L${b.x+105},${b.y+42}" stroke="var(--muted)" stroke-width="2"/>`;}).join('')}${shown.map(n=>`<g><rect x="${n.x}" y="${n.y}" width="210" height="84" rx="12" fill="var(--surface)" stroke="${n.color}" stroke-width="${n.id===highlight?6:3}"/><foreignObject x="${n.x+14}" y="${n.y+12}" width="182" height="60"><div xmlns="http://www.w3.org/1999/xhtml" class="slide-node-label">${esc(n.text)}</div></foreignObject></g>`).join('')}</svg>`;};
 const render=()=>{const s=slides[index],n=nodes.get(s.id),sections=n?readSections(n):{};let html='';if(s.type==='overview')html=`<h1>${esc(p.name)}</h1><p>Visão geral · ${order.length} ideias selecionadas</p>${graph(s.ids)}`;else if(s.type==='compare')html=`<h1>Qual ideia vamos escolher?</h1><div class="slide-comparison">${s.ids.map(id=>{const n=nodes.get(id),a=readSections(n);return `<article><h2>${esc(n.text)}</h2><h3>Público</h3><p>${esc(n.review?.audience||'A definir')}</p><h3>Primeira versão</h3><p>${esc(a.mvp||'A definir')}</p><h3>Dificuldade</h3><p>${esc(n.review?.difficulty||'Não estimada')}</p><h3>O que falta validar</h3><p>${esc(n.review?.validation||'A definir')}</p></article>`;}).join('')}</div>`;else html=`<h1>${esc(n.text)}</h1><div class="slide-columns">${graph(s.ids,s.feature||s.id)}<article>${s.type==='feature'?`<h2>${esc(nodes.get(s.feature).text)}</h2><p>${esc(nodes.get(s.feature).notes||'Funcionalidade desta proposta.')}</p>`:`<h2>Proposta / problema</h2><p>${esc(sections.problem||n.notes||'Ainda não definido')}</p><h2>Como funciona</h2><p>${esc(sections.operation||'Ainda não definido')}</p><h2>Primeira versão</h2><p>${esc(sections.mvp||'Ainda não definida')}</p>`}</article></div>`;stage.querySelector('.slide-body').innerHTML=html;stage.querySelector('.slide-count').textContent=`${index+1} / ${slides.length}`;stage.querySelector('[data-action=prev]').disabled=index===0;stage.querySelector('[data-action=next]').disabled=index===slides.length-1;};
 const move=delta=>{index=Math.max(0,Math.min(slides.length-1,index+delta));render();};stage.onclick=async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='prev')move(-1);if(action==='next')move(1);if(action==='exit')stage.close();if(action==='full'){try{if(document.fullscreenElement===stage)await document.exitFullscreen();else await stage.requestFullscreen();}catch{stage.querySelector('[data-action=full]').textContent='Tela cheia indisponível';}}};stage.onkeydown=e=>{if(e.target.matches('input,textarea,select'))return;if(['ArrowRight','ArrowDown',' ','PageDown'].includes(e.key)){e.preventDefault();move(1);}if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();move(-1);}if(e.key==='Home'){e.preventDefault();index=0;render();}if(e.key==='End'){e.preventDefault();index=slides.length-1;render();}};stage.onclose=()=>{if(document.fullscreenElement===stage)document.exitFullscreen().catch(()=>{});stage.remove();};render();
}
